import{_ as t,o as a,c as i,a9 as n}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Julia and native performance tools","description":"","frontmatter":{},"headers":[],"relativePath":"native-profiling.md","filePath":"native-profiling.md","lastUpdated":null}'),r={name:"native-profiling.md"};function s(o,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="Julia-and-native-performance-tools" tabindex="-1">Julia and native performance tools <a class="header-anchor" href="#Julia-and-native-performance-tools" aria-label="Permalink to &quot;Julia and native performance tools {#Julia-and-native-performance-tools}&quot;">​</a></h1><p>Start with the question in the table below, then read the corresponding tool section. For a reproducible Julia profile, use the <a href="/PerfChecker/dev/tutorials/bibliography#Select-a-package,-workload-and-collector">Bibliography collector commands</a>. Native tools additionally need a compatible installation and a workload script.</p><p><code>tool_catalog()</code> lists PerfChecker collectors, optional extensions and external tools, using <code>data/tool-catalog.json</code>. The web and VS Code interfaces display the same list. Check an entry&#39;s integration and platform fields before using it. This inventory was reviewed on 12 September 2026.</p><h2 id="Choose-an-instrument-from-the-question" tabindex="-1">Choose an instrument from the question <a class="header-anchor" href="#Choose-an-instrument-from-the-question" aria-label="Permalink to &quot;Choose an instrument from the question {#Choose-an-instrument-from-the-question}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Question</th><th style="text-align:right;">First measurement</th><th style="text-align:right;">Follow-up evidence</th><th style="text-align:right;">Main limitation</th></tr></thead><tbody><tr><td style="text-align:right;">Is an operation slower?</td><td style="text-align:right;">BenchmarkTools or Chairmarks distribution</td><td style="text-align:right;">Same input and oracle, repeated sessions</td><td style="text-align:right;">Setup, JIT and environment differences can dominate</td></tr><tr><td style="text-align:right;">Where does CPU time go?</td><td style="text-align:right;">Julia Profile, with C frames when needed</td><td style="text-align:right;">perf or VTune; symbols for native libraries</td><td style="text-align:right;">Sampling noise; unresolved/inlined frames</td></tr><tr><td style="text-align:right;">Why is wall time larger than CPU time?</td><td style="text-align:right;">Wall profile plus workload timeline</td><td style="text-align:right;">ETW/WPR on Windows; perf/bpftrace on Linux</td><td style="text-align:right;">Other processes, scheduling and I/O attribution</td></tr><tr><td style="text-align:right;">Why does the Julia heap allocate?</td><td style="text-align:right;">Profile.Allocs, GC counters, heap snapshots</td><td style="text-align:right;">AllocCheck and inference inspection</td><td style="text-align:right;">Native allocations are a different quantity</td></tr><tr><td style="text-align:right;">Why does native memory grow?</td><td style="text-align:right;">RSS/private memory and explicit resource ledgers</td><td style="text-align:right;">Memcheck, Massif, heaptrack</td><td style="text-align:right;">Allocator pools, mappings and retained capacity differ</td></tr><tr><td style="text-align:right;">Why is startup slow?</td><td style="text-align:right;">Fresh-process startup/first-call measurement</td><td style="text-align:right;">SnoopCompile; runtime timing zones</td><td style="text-align:right;">Warm measurements conceal compilation and imports</td></tr><tr><td style="text-align:right;">Why does threading scale badly?</td><td style="text-align:right;">Same workload across declared thread counts</td><td style="text-align:right;">Counters, affinity, lock events and timelines</td><td style="text-align:right;">NUMA, quotas and oversubscription confound results</td></tr><tr><td style="text-align:right;">Is a device doing the work?</td><td style="text-align:right;">Verified device identity and synchronized operation</td><td style="text-align:right;">CUDA/Nsight, ROCm tools, VTune</td><td style="text-align:right;">Async launch time is not completed device execution</td></tr><tr><td style="text-align:right;">Is a native dependency incorrect?</td><td style="text-align:right;">Functional oracle and dependency provenance</td><td style="text-align:right;">Sanitizers or Memcheck</td><td style="text-align:right;">Instrumented execution does not measure native speed</td></tr></tbody></table><p>Julia&#39;s own profiler can include native C/Fortran frames. Allocation profiling describes Julia allocations; it must not be presented as all process memory. Keep warmup and asynchronous completion explicit. See the <a href="https://docs.julialang.org/en/v1/manual/profile/" target="_blank" rel="noreferrer">Julia profiling manual</a>.</p><h2 id="Static-analysis-and-compilation" tabindex="-1">Static analysis and compilation <a class="header-anchor" href="#Static-analysis-and-compilation" aria-label="Permalink to &quot;Static analysis and compilation {#Static-analysis-and-compilation}&quot;">​</a></h2><p>A static analyzer inspects code and its inferred or compiled representation. It can find suspicious operations without timing an actual Bibliography export. A diagnostic therefore points to a hypothesis: for example, an uncertain type may lead to dynamic method selection, but its practical cost still needs a measurement. Compilation tools answer another question: how much work happens before the operation can run efficiently?</p><h3 id="JET:-possible-inference-and-dispatch-problems" tabindex="-1">JET: possible inference and dispatch problems <a class="header-anchor" href="#JET:-possible-inference-and-dispatch-problems" aria-label="Permalink to &quot;JET: possible inference and dispatch problems {#JET:-possible-inference-and-dispatch-problems}&quot;">​</a></h3><p>JET&#39;s optimization analysis follows the inferred call graph and reports potential performance pitfalls. <strong>Runtime dispatch</strong> means that selecting a method still depends on information available during execution. For Bibliography, a report inside the export path can suggest which call to inspect. Diagnostic counts are not time measurements, and clearing a warning does not establish a speedup. See <a href="https://github.com/aviatesk/JET.jl/blob/master/docs/src/optanalysis.md" target="_blank" rel="noreferrer">JET&#39;s optimization analysis</a>.</p><h3 id="Cthulhu:-inspect-the-compiler&#39;s-view-interactively" tabindex="-1">Cthulhu: inspect the compiler&#39;s view interactively <a class="header-anchor" href="#Cthulhu:-inspect-the-compiler&#39;s-view-interactively" aria-label="Permalink to &quot;Cthulhu: inspect the compiler&#39;s view interactively {#Cthulhu:-inspect-the-compiler&#39;s-view-interactively}&quot;">​</a></h3><p>Cthulhu lets you descend through inferred code and inspect where type information becomes less precise. It is useful when a report points into several layers of calls and you need to understand how the uncertainty arose. The displayed types describe the compiler&#39;s analysis, not a frequency measured while exporting. See <a href="https://github.com/JuliaDebug/Cthulhu.jl" target="_blank" rel="noreferrer">Cthulhu</a>.</p><h3 id="SnoopCompile:-investigate-compilation-work" tabindex="-1">SnoopCompile: investigate compilation work <a class="header-anchor" href="#SnoopCompile:-investigate-compilation-work" aria-label="Permalink to &quot;SnoopCompile: investigate compilation work {#SnoopCompile:-investigate-compilation-work}&quot;">​</a></h3><p>SnoopCompile helps examine inference and the calls that trigger it. <strong>Inference</strong> is the compiler&#39;s analysis of possible types; it contributes to preparing specialized code. For a slow first Bibliography export, inspect this work separately from the warm export benchmark. Inference timings do not represent the complete startup interval or all later execution costs. See <a href="https://juliadebug.github.io/SnoopCompile.jl/dev/tutorials/snoop_inference_analysis/" target="_blank" rel="noreferrer">SnoopCompile&#39;s inference tutorial</a>.</p><h3 id="AllocCheck:-inspect-possible-allocation-paths" tabindex="-1">AllocCheck: inspect possible allocation paths <a class="header-anchor" href="#AllocCheck:-inspect-possible-allocation-paths" aria-label="Permalink to &quot;AllocCheck: inspect possible allocation paths {#AllocCheck:-inspect-possible-allocation-paths}&quot;">​</a></h3><p>AllocCheck inspects generated LLVM code for possible allocation and dispatch. It can help investigate a path intended to avoid allocation, including branches that a small measured fixture might not exercise. Its exception-path policy matters and its entry wrapper has overhead. Read a finding as a possible code path, then measure the relevant Bibliography input; it is not an allocation byte counter. See <a href="https://github.com/JuliaLang/AllocCheck.jl" target="_blank" rel="noreferrer">AllocCheck</a>.</p><h3 id="Precompilation-tools-and-package-quality" tabindex="-1">Precompilation tools and package quality <a class="header-anchor" href="#Precompilation-tools-and-package-quality" aria-label="Permalink to &quot;Precompilation tools and package quality {#Precompilation-tools-and-package-quality}&quot;">​</a></h3><p>PrecompileTools and PackageCompiler change the artifact/startup tradeoff. Compare cold imports, first invocation, steady-state performance, build cost and artifact size separately. Aqua and property-testing tools remain quality/correctness checks, not performance profilers.</p><p>For example, Aqua checks issues such as ambiguous methods and unused type parameters. An ambiguity means Julia may lack one most-specific applicable method for some call. This is valuable package-quality evidence, but an Aqua pass does not establish an export latency or memory budget. See <a href="https://juliatesting.github.io/Aqua.jl/dev/test_all/" target="_blank" rel="noreferrer">Aqua&#39;s checks</a>.</p><h2 id="Linux-native-tools" tabindex="-1">Linux native tools <a class="header-anchor" href="#Linux-native-tools" aria-label="Permalink to &quot;Linux native tools {#Linux-native-tools}&quot;">​</a></h2><p>Native tools can inspect the Julia process and code from its C, C++, Fortran or other compiled dependencies. Their units matter: instruction counts measure executed instructions, cache misses concern memory accesses that were not served by a particular cache, and heap profiles concern allocated or retained memory. None is a direct substitute for elapsed seconds. Start with the suspected cause and select the matching evidence, rather than collecting every counter.</p><p><code>native_tool_plan</code> prepares argument vectors for Memcheck, Callgrind, Cachegrind, Massif, heaptrack, perf and VTune. It checks local executable presence without starting a process or installing anything. These are command plans; execution, artifact import and causal diagnosis are not qualified adapters yet.</p><p>This plan example assumes you supplied <code>native_case.jl</code>, a prepared <code>perf</code> project and a suppression file matching your Julia build. It does not execute that workload:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plan </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> native_tool_plan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:memcheck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;native_case.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;results/memcheck&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    suppressions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contrib/valgrind-julia.supp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Valgrind needs <code>--smc-check=all-non-file</code> for Julia&#39;s JIT. The plan includes child process tracing and per-process artifact names. Match suppression files to the runtime. Some investigations need Julia built with memory pools disabled; some CPU targets are unsupported. A zero exit is insufficient without the workload oracle and reviewed diagnostics. See <a href="https://docs.julialang.org/en/v1/devdocs/valgrind/" target="_blank" rel="noreferrer">Julia&#39;s Valgrind guidance</a>.</p><h3 id="Memcheck:-invalid-memory-operations-and-leaks" tabindex="-1">Memcheck: invalid memory operations and leaks <a class="header-anchor" href="#Memcheck:-invalid-memory-operations-and-leaks" aria-label="Permalink to &quot;Memcheck: invalid memory operations and leaks {#Memcheck:-invalid-memory-operations-and-leaks}&quot;">​</a></h3><p>Memcheck looks for invalid reads or writes, use of uninitialized values and incorrect memory deallocation. These are correctness diagnostics, not speed scores. For a Julia workload calling a native library, inspect the reported stack and allocation origin to identify which layer owns the memory. Running under Memcheck changes execution cost substantially; use an ordinary benchmark for the final performance comparison.</p><p>Its leak report distinguishes <strong>definitely lost</strong> blocks, for which it cannot find a pointer, from <strong>still reachable</strong> blocks, for which a pointer remains. Reachable memory can include intentionally retained runtime state. Bytes and block counts describe different aspects of that report; neither equals Bibliography&#39;s per-export Julia allocation count. Review leak categories, suppressions and the workload&#39;s lifetime together. See the <a href="https://valgrind.org/docs/manual/mc-manual.html" target="_blank" rel="noreferrer">Memcheck manual</a>.</p><h3 id="Callgrind:-instruction-cost-along-a-call-graph" tabindex="-1">Callgrind: instruction cost along a call graph <a class="header-anchor" href="#Callgrind:-instruction-cost-along-a-call-graph" aria-label="Permalink to &quot;Callgrind: instruction cost along a call graph {#Callgrind:-instruction-cost-along-a-call-graph}&quot;">​</a></h3><p>Callgrind records instruction execution and calling relationships. <strong>Self cost</strong> belongs to a function itself; <strong>inclusive cost</strong> includes its callees. A large inclusive cost at a Bibliography entry point suggests following its calls to find where the work occurs. Do not add that total to the same work shown under its children. A call count describes calls, whereas an instruction count describes executed machine instructions.</p><p>Fewer instructions can suggest less work, but instructions have different costs and memory stalls also matter. Callgrind does not turn an instruction count into the native elapsed time of an export. Confirm an improvement with the same uninstrumented workload. See the <a href="https://valgrind.org/docs/manual/cl-manual.html" target="_blank" rel="noreferrer">Callgrind manual</a>.</p><h3 id="Cachegrind:-instructions-and-optional-simulated-caches" tabindex="-1">Cachegrind: instructions and optional simulated caches <a class="header-anchor" href="#Cachegrind:-instructions-and-optional-simulated-caches" aria-label="Permalink to &quot;Cachegrind: instructions and optional simulated caches {#Cachegrind:-instructions-and-optional-simulated-caches}&quot;">​</a></h3><p>Cachegrind counts instructions and can simulate caches and branch prediction. A <strong>cache miss</strong> means an access was not served by the selected simulated cache; a <strong>branch misprediction</strong> means a simulated prediction chose the wrong branch. These can help investigate access patterns or conditional code. Read each counter&#39;s label and denominator before comparing miss rates.</p><p>Cache and branch simulation are disabled by default in current versions and do not faithfully model modern processors. Record the tool version and enabled simulation options. These results can motivate a Bibliography implementation experiment, but they are not measurements of the current CPU&#39;s exact cache behavior or a substitute for elapsed time. See the <a href="https://valgrind.org/docs/manual/cg-manual.html" target="_blank" rel="noreferrer">Cachegrind manual</a>.</p><h3 id="Massif-and-heaptrack:-native-heap-growth" tabindex="-1">Massif and heaptrack: native heap growth <a class="header-anchor" href="#Massif-and-heaptrack:-native-heap-growth" aria-label="Permalink to &quot;Massif and heaptrack: native heap growth {#Massif-and-heaptrack:-native-heap-growth}&quot;">​</a></h3><p>Massif samples heap usage and attributes it to allocation paths. A <strong>peak</strong> is the largest recorded usage during the observed execution; an endpoint is usage at its end. Neither is the cumulative volume allocated over every export. Read the horizontal axis too: Massif&#39;s time axis can represent instructions, milliseconds or allocated bytes depending on configuration. Its default heap view is not all process RAM. See the <a href="https://valgrind.org/docs/manual/ms-manual.html" target="_blank" rel="noreferrer">Massif manual</a>.</p><p>heaptrack records native allocation stacks and helps separate temporary allocation activity from retained memory. Repeating the same Bibliography operation can help reveal whether a native dependency retains more memory each time, but growth alone does not establish a leak: caches and allocator capacity also matter. Neither tool replaces analysis of which Julia objects remain reachable. See <a href="https://github.com/KDE/heaptrack" target="_blank" rel="noreferrer">heaptrack</a>.</p><h3 id="Hardware-counters:-events-on-the-actual-processor" tabindex="-1">Hardware counters: events on the actual processor <a class="header-anchor" href="#Hardware-counters:-events-on-the-actual-processor" aria-label="Permalink to &quot;Hardware counters: events on the actual processor {#Hardware-counters:-events-on-the-actual-processor}&quot;">​</a></h3><p>perf, LIKWID and PAPI can supply hardware/scheduler evidence where the kernel, hardware and permissions support it. Counter multiplexing and affinity must be recorded; unavailable counters must not become zero values. The <a href="https://juliaperf.github.io/LIKWID.jl/stable/" target="_blank" rel="noreferrer">LIKWID wrapper</a> documents its topology and counter facilities.</p><p>A <strong>cycle</strong> is a processor clock cycle; an <strong>instruction</strong> is an executed machine instruction. Their ratio, instructions per cycle, describes execution behavior under that counter configuration, not useful Bibliography exports per second. <strong>Multiplexing</strong> means the tool alternates limited hardware counters between requested events and may scale their totals. Compare compatible event definitions and report the measured interval; a missing or unsupported event is not evidence that it never occurred.</p><h2 id="Windows,-traces-and-instrumented-builds" tabindex="-1">Windows, traces and instrumented builds <a class="header-anchor" href="#Windows,-traces-and-instrumented-builds" aria-label="Permalink to &quot;Windows, traces and instrumented builds {#Windows,-traces-and-instrumented-builds}&quot;">​</a></h2><p>A trace records events over time: for example, a thread becoming runnable, waiting for I/O, or returning from a system operation. This timeline helps investigate why a Julia operation took a long time despite little visible CPU work. A thread that is ready to run can still wait for the operating system to schedule it. Attribute events to the measured worker before blaming the package.</p><p>WPR records ETW traces and WPA analyzes them: useful for scheduling, I/O and system activity around Julia and its native dependencies. This is a separate trace path, not a Julia allocation collector. VTune is another optional CPU analysis route. See the <a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/" target="_blank" rel="noreferrer">Windows Performance Toolkit</a>.</p><p>Julia exposes profiler build support for Tracy and VTune timing zones. Its DTrace/bpftrace probes provide another event-level view. Probe and zone coverage depends on the actual build. See <a href="https://docs.julialang.org/en/v1/devdocs/external_profilers/" target="_blank" rel="noreferrer">external profiler support</a> and <a href="https://docs.julialang.org/en/v1/devdocs/probes/" target="_blank" rel="noreferrer">runtime probes</a>.</p><p>Sanitizers require compatible instrumented runtime/library builds and diagnose memory errors or races. Their timing and memory overhead cannot be treated as unmodified production performance. See <a href="https://docs.julialang.org/en/v1/devdocs/sanitizers/" target="_blank" rel="noreferrer">Julia sanitizer support</a>.</p><h2 id="GPU,-distributed-and-foreign-runtimes" tabindex="-1">GPU, distributed and foreign runtimes <a class="header-anchor" href="#GPU,-distributed-and-foreign-runtimes" aria-label="Permalink to &quot;GPU, distributed and foreign runtimes {#GPU,-distributed-and-foreign-runtimes}&quot;">​</a></h2><p>For CUDA, synchronize before comparing completed operation costs and separate host/device transfer from kernels. Nsight Systems investigates timelines; Nsight Compute investigates individual kernels. See <a href="https://cuda.juliagpu.org/stable/development/profiling/" target="_blank" rel="noreferrer">CUDA.jl profiling</a> and <a href="https://docs.nvidia.com/nsight-systems/UserGuide/index.html" target="_blank" rel="noreferrer">Nsight Systems</a>.</p><p>AMDGPU/rocprof, oneAPI/VTune, MPI/Dagger traces, NPU execution providers and device energy counters remain environment-specific integration candidates in the catalogue. Native dependency fingerprints, actual devices, transfer boundaries, rank/process identities, synchronization and fallback detection are required before interpreting these measurements. Mac tooling stays inventoried; no Mac validation is claimed.</p><h2 id="Qualification-experiment" tabindex="-1">Qualification experiment <a class="header-anchor" href="#Qualification-experiment" aria-label="Permalink to &quot;Qualification experiment {#Qualification-experiment}&quot;">​</a></h2><p>Before calling a native adapter supported, run four controls: a healthy workload, a known native allocation/leak, a known CPU hotspot, and a child-process workload. Check symbol/source attribution, nonzero diagnostics for injected defects, bounded cancellation, artifact completeness and matching dependency identities. Then run unchanged controls without the profiler to measure its perturbation. Windows and Linux need their own evidence; WSL results describe the Linux guest.</p>`,50)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
